const COP=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n||0);
const KEY='lhAdminV4', OLD='lhAdminV3', GAME=2000, ADMIN_PIN='1234'; let catalog=[], baseCatalog=[], inventoryAdmin=false;
let S=JSON.parse(localStorage.getItem(KEY)||'null')||migrate(JSON.parse(localStorage.getItem(OLD)||'null'))||init();
if((S.uiRelease||0)<4181){S.uiSettings=S.uiSettings||{};if(!S.uiSettings.billarTheme)S.uiSettings.billarTheme='herraduraos';S.uiRelease=4181;localStorage.setItem(KEY,JSON.stringify(S));}
function init(){return{version:4,tables:[...Array(4)].map((_,i)=>({id:'B'+(i+1),type:'billar',name:'Billar '+(i+1),account:null})).concat([...Array(18)].map((_,i)=>({id:'C'+(i+1),type:'consumo',name:'Consumo '+(i+1),account:null}))),sales:[],expenses:[],shifts:[],inventory:{},waitresses:['Mesera turno 1','Mesera turno 2'],audit:[],customProducts:[],inventoryMovements:[],inventorySettings:{defaultMin:5},productOverrides:{},uiSettings:{billarTheme:'herradura',consumoTheme:'elegante',customerTheme:'premium'}}}
function migrate(o){if(!o)return null;o.version=4;o.audit=o.audit||[];o.customProducts=o.customProducts||[];o.inventoryMovements=o.inventoryMovements||[];o.inventorySettings=o.inventorySettings||{defaultMin:5};o.productOverrides=o.productOverrides||{};o.uiSettings=o.uiSettings||{billarTheme:'herradura',consumoTheme:'elegante',customerTheme:'premium'};for(const x of o.tables||[]){if(x.account&&x.type==='billar'){let a=x.account;a.rounds=a.rounds||[];for(const g of a.games||[])a.rounds.push({id:Date.now()+Math.random(),status:'closed',loser:g.loser||'Sin identificar',items:g.items||[],gameFee:GAME,createdAt:new Date().toISOString(),closedAt:new Date().toISOString()});a.games=[];a.activeRound=a.activeRound||{id:Date.now()+Math.random(),status:'active',items:[],createdAt:new Date().toISOString(),source:'Nueva partida'};a.players=a.players||[];a.playerExtras=a.playerExtras||[];a.payments=a.payments||[]}}return o}
function save(note){if(note)S.audit.push({ts:new Date().toISOString(),note});localStorage.setItem(KEY,JSON.stringify(S));try{new BroadcastChannel('lh-live').postMessage({type:'update',ts:Date.now()})}catch(e){}renderHome()}
function stamp(){return new Date().toLocaleString('es-CO')};function t(id){return S.tables.find(x=>x.id===id)}
fetch('catalog.json').then(r=>r.json()).then(x=>{baseCatalog=x;refreshCatalog();for(const p of catalog)if(S.inventory[p.id]==null)S.inventory[p.id]=p.stock||0;save();renderInventory()});
function refreshCatalog(){catalog=[...baseCatalog.map(p=>({...p,...(S.productOverrides?.[p.id]||{})})),...(S.customProducts||[])];}
function unitCost(p){if(!p)return 0;if(p.recipe?.length)return p.recipe.reduce((z,r)=>{let q=catalog.find(x=>x.id===r.productId);return z+unitCost(q)*(r.qty||0)},0);return +(p.cost||0)}
function itemUnitCost(i){if(Number.isFinite(+i.cost))return +i.cost;return unitCost(catalog.find(p=>p.id===i.id))}
function accountCOGS(a,player=null){let z=0;if(a?.rounds)for(const r of a.rounds)if(!player||r.loser===player)for(const i of r.items||[])z+=itemUnitCost(i)*(i.qty||1);if(a?.playerExtras)for(const i of a.playerExtras)if(!player||i.player===player)z+=itemUnitCost(i)*(i.qty||1);if(!player&&a?.loose)for(const i of a.loose)z+=itemUnitCost(i)*(i.qty||1);if(!player&&a?.consumptionRounds)for(const r of a.consumptionRounds)for(const i of r.items||[])z+=itemUnitCost(i)*(i.qty||1);if(!player&&a?.consumptionExtras)for(const i of a.consumptionExtras)z+=itemUnitCost(i)*(i.qty||1);for(const d of a?.returns||[])if(!player||d.player===player)z-=itemUnitCost(d)*(d.qty||1);return Math.max(0,z)}
function remainingCOGS(a){let recognized=(a?.payments||[]).reduce((z,p)=>z+(+p.cogs||0),0);return Math.max(0,accountCOGS(a)-recognized)}
function posResetViewport(target){
  // Desktop Safari/Chrome can preserve the old document scroll position when a SPA view changes.
  // Reset every possible scrolling root, then anchor the active module under the sticky header.
  try{window.scrollTo(0,0)}catch(e){}
  document.documentElement.scrollTop=0;
  document.body.scrollTop=0;
  const main=document.querySelector('main');
  if(main){main.scrollTop=0;main.scrollLeft=0}
  if(target){
    target.scrollIntoView({block:'start',inline:'nearest',behavior:'auto'});
    // Keep the top of the module visible below the sticky desktop header.
    if(window.matchMedia('(min-width:1100px)').matches){
      const y=target.getBoundingClientRect().top+window.pageYOffset-96;
      window.scrollTo(0,Math.max(0,y));
    }
  }
}
function posMarkNav(id){
  document.querySelectorAll('.bottom button').forEach(b=>b.classList.remove('posActive'));
  const key=id==='tablesView'?(window.__lhTableType||'') : id;
  document.querySelectorAll('.bottom button').forEach(b=>{
    const oc=b.getAttribute('onclick')||'';
    if((key==='billar'&&oc.includes("showTables('billar')"))||(key==='consumo'&&oc.includes("showTables('consumo')"))||(key!=='billar'&&key!=='consumo'&&oc.includes("showView('"+key+"')"))) b.classList.add('posActive');
  });
}
function showView(id){
  document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));
  const target=document.getElementById(id);
  target.classList.add('active');
  if(id==='inventory')renderInventory();if(id==='sales')renderSales();if(id==='reports')renderReports();if(id==='expenses')renderExpenses();if(id==='shifts')renderShift();
  posMarkNav(id);
  posResetViewport(target);
  requestAnimationFrame(()=>{posResetViewport(target);requestAnimationFrame(()=>posResetViewport(target))});
}
function modal(h){sheet.innerHTML=h;modalEl.classList.add('show')}function closeModal(){modalEl.classList.remove('show')}function backToTables(type){closeModal();showTables(type)}function modalNav(back,label='Volver'){return `<div class="modalNav"><button class="navBack" onclick="${back}">← ${label}</button><button class="navHome" onclick="closeModal();showView('home')">🏠 Inicio</button></div>`}
function roundConsumption(r){return(r?.items||[]).reduce((s,i)=>s+i.price*i.qty,0)}
function grossTotal(a){let gross=(a?.rounds||[]).reduce((s,r)=>s+GAME+roundConsumption(r),0)+(a?.loose||[]).reduce((s,i)=>s+i.price*i.qty,0)+(a?.playerExtras||[]).reduce((s,i)=>s+i.price*i.qty,0)+(a?.consumptionRounds||[]).reduce((s,r)=>s+(r.items||[]).reduce((z,i)=>z+i.price*i.qty,0),0)+(a?.consumptionExtras||[]).reduce((s,i)=>s+i.price*i.qty,0);return Math.max(0,gross-(a?.returns||[]).reduce((s,d)=>s+d.credit,0))}
function paidTotal(a){return(a?.payments||[]).reduce((s,p)=>s+p.amount,0)}
function closedTotal(a){return Math.max(0,grossTotal(a)-paidTotal(a))}
function pendingTotal(a){return roundConsumption(a?.activeRound)}
function displayTotal(a,type){return closedTotal(a)+(type==='billar'?pendingTotal(a):0)}
function renderHome(){let today=new Date().toDateString(),p=S.sales.filter(x=>new Date(x.ts).toDateString()===today);kSales.textContent=COP(p.reduce((s,x)=>s+x.total,0));kCash.textContent=COP(p.reduce((s,x)=>s+x.cash,0));kTransfer.textContent=COP(p.reduce((s,x)=>s+x.transfer,0));kOpen.textContent=S.tables.filter(x=>x.account).length;status.innerHTML=`<p>🎱 ${S.tables.filter(x=>x.type==='billar'&&x.account).length}/4 mesas de billar activas</p><p>🍺 ${S.tables.filter(x=>x.type==='consumo'&&x.account).length}/18 mesas de consumo activas</p><p>📦 ${catalog.filter(p=>(S.inventory[p.id]||0)<=5&&p.type==='stock').length} productos con existencia ≤ 5</p>`}
function showTables(type){window.__lhTableType=type;showView('tablesView');document.getElementById('tablesView').className='view active tableExperience '+type+'Theme theme-'+(S.uiSettings?.[type+'Theme']||'herradura');posMarkNav('tablesView');posResetViewport(document.getElementById('tablesView'));if(type==='billar'){let bt=S.tables.filter(x=>x.type==='billar'),busy=bt.filter(x=>x.account).length;tablesTitle.innerHTML=`🎱 Mesas de billar <span class="osStats"><span class="osStat"><i></i>${busy} En juego</span><span class="osStat">${bt.length-busy} Disponibles</span></span>`}else{let ct=S.tables.filter(x=>x.type==='consumo'),busy=ct.filter(x=>x.account).length;tablesTitle.innerHTML=`🍺 Mesas de consumo <span class="osStats"><span class="osStat openStat"><i></i>${busy} ${busy===1?'Abierta':'Abiertas'}</span><span class="osStat">${ct.length-busy} ${(ct.length-busy)===1?'Disponible':'Disponibles'}</span></span>`};tables.innerHTML=S.tables.filter(x=>x.type===type).map(x=>`<div class="card tableCard ${x.account?'busy':''}"><img class="tablePhoto" src="billar-luxury-clean.jpg" alt="" aria-hidden="true"><span class="pill">${x.account?(type==='billar'?'EN JUEGO':'ABIERTA'):'DISPONIBLE'}</span><h3>${x.name}</h3><div>${x.account?x.account.group:'Libre'}</div><div class="amt">${x.account?COP(displayTotal(x.account,x.type)):'—'}</div>${x.account?`<div class="actions"><button class="primary" onclick="openAccount('${x.id}')">Gestionar</button>${x.type==='billar'?`<button onclick="openCustomer('${x.id}')">📺 Cliente</button>`:''}<button onclick="move('${x.id}')">⇄</button><button class="gold" onclick="pay('${x.id}')">Cobrar</button></div>`:`<button onclick="newAccount('${x.id}')">+ Abrir cuenta</button>`}</div>`).join('')}
function newAccount(id){let x=t(id);modal(`${modalNav("backToTables('${x.type}')",'Mesas')}<h2>Abrir ${x.name}</h2><div class="field"><label>Cliente / grupo</label><input id="group" placeholder="Ej. Carlos y amigos"></div><div class="field"><label>Mesera</label><select id="waitress">${S.waitresses.map(x=>`<option>${x}</option>`).join('')}</select></div>${x.type==='billar'?`<div class="projectionBox"><div><b>📺 Pantalla del cliente</b><small>Prepara la vista profesional para proyectar esta mesa.</small></div><button onclick="previewCustomer('${id}')">Vista previa</button></div>`:''}<button class="gold wide" onclick="confirmOpen('${id}')">Abrir cuenta</button>`)}
function confirmOpen(id){let x=t(id);x.account={group:group.value||'Cliente',waitress:waitress.value,rounds:[],activeRound:x.type==='billar'?newRound('Nueva partida'):null,loose:[],history:[stamp()+' · Cuenta abierta'],players:[],people:[],playerExtras:[],payments:[],returns:[]};save(`Cuenta abierta ${x.name}`);closeModal();openAccount(id)}
function newRound(source='Nueva partida',items=[]){return{id:Date.now()+Math.random(),status:'active',items:items.map(i=>({...i})),createdAt:new Date().toISOString(),source}}
function openAccount(id){let x=t(id),a=x.account;if(x.type==='billar')openBilliard(id);else openConsumption(id)}
function openBilliard(id){let x=t(id),a=x.account,r=a.activeRound||newRound();a.activeRound=r;let n=(a.rounds?.length||0)+1;modal(`${modalNav("backToTables('billar')",'Mesas')}<div class="billiardManage"><div class="accountHead"><div><small>${x.name} · ${a.group}</small><h2>🎱 Partida ${n}</h2><span class="state activeState">● EN CURSO</span></div><div class="roundMoney"><small>Consumo ronda</small><strong>${COP(roundConsumption(r))}</strong></div></div><div class="notice compact manageHint">Los productos se acumulan en esta ronda. Al terminar, consumo + ${COP(GAME)} se asignan al perdedor.</div><div class="quickActions"><button class="finish" onclick="finishRound('${id}')">🏁 Terminar partida</button><button onclick="duplicatePreview('${id}')" ${a.rounds.length?'':'disabled'}>🔁 Duplicar anterior</button><button onclick="extraPlayer('${id}')">➕ Extra persona</button><button onclick="openCustomer('${id}')">📺 Vista cliente</button><button onclick="startReturn('${id}')">↩️ Devolución</button></div><section class="orderPanel"><div class="orderTitle"><div><small>COMANDA ACTIVA</small><h3>🧾 Pedido · Partida ${n}</h3></div><div><small>Subtotal</small><strong>${COP(roundConsumption(r))}</strong></div></div><div class="orderCart">${roundItems(r,id)}</div></section><div class="catalogHead"><div><small>CATÁLOGO</small><h3>Agregar productos a la ronda</h3></div><small>Toca un producto para sumarlo</small></div><div class="chips">${categoryButtons(id)}</div><input class="search" id="prodSearch" placeholder="🔎 Buscar producto…" oninput="renderProducts('${id}')"><div id="productBox" class="products"></div><h3 class="manageSectionTitle">Cuentas acumuladas</h3><div class="card inner">${playerBalances(a,id)}</div><h3 class="manageSectionTitle">Historial de partidas</h3><div class="card inner">${roundHistory(a,id)}</div><div class="stickyActions"><button onclick="move('${id}')">⇄ Cambiar mesa</button><button onclick="viewAccount('${id}')">🧾 Ver cuenta</button><button class="gold" onclick="pay('${id}')">💰 Cobrar</button></div></div>`);renderProducts(id)}
let consumptionDraft={};
function consumptionDraftFor(id){return consumptionDraft[id]||(consumptionDraft[id]={items:[],requester:'Cuenta general'})}
function consumptionDraftTotal(id){return consumptionDraftFor(id).items.reduce((z,i)=>z+i.price*i.qty,0)}
function consumptionPeople(a){let out=[];for(const r of a.consumptionRounds||[])if(r.requester&&r.requester!=='Cuenta general'&&!out.some(n=>playerKey(n)===playerKey(r.requester)))out.push(r.requester);for(const e of a.consumptionExtras||[])if(e.responsible&&!out.some(n=>playerKey(n)===playerKey(e.responsible)))out.push(e.responsible);return out}
function consumptionRoundTotal(r){return(r.items||[]).reduce((z,i)=>z+i.price*i.qty,0)}
function openConsumption(id){let x=t(id),a=x.account;a.consumptionRounds=a.consumptionRounds||[];a.consumptionExtras=a.consumptionExtras||[];let d=consumptionDraftFor(id),people=consumptionPeople(a);modal(`${modalNav("backToTables('consumo')",'Mesas')}<div class="consumoManage"><div class="accountHead consumoHead"><div><small>${x.name} · ${a.waitress}</small><h2>🍺 ${a.group}</h2><span class="state activeState">● MESA ABIERTA</span></div><div class="roundMoney"><small>Saldo pendiente</small><strong>${COP(closedTotal(a))}</strong></div></div><div class="consumoHero"><div><small>COMANDA ACTIVA</small><h3>🧾 Nueva ronda</h3><p>Identifica quién pidió la ronda. Esto organiza la cuenta, pero no obliga a que esa persona sea quien pague al final.</p></div><div class="heroTotal"><small>Por guardar</small><strong>${COP(consumptionDraftTotal(id))}</strong></div></div><div class="requesterBox"><b>👤 ¿Quién pidió esta ronda?</b><div class="personChips"><button class="${d.requester==='Cuenta general'?'selectedPerson':''}" onclick="setConsumptionRequester('${id}','Cuenta general')">👥 Cuenta general</button>${people.map(n=>`<button class="${d.requester===n?'selectedPerson':''}" onclick="setConsumptionRequester('${id}','${esc(n)}')">👤 ${n}</button>`).join('')}</div><div class="newRequester"><input id="newRequester" placeholder="Nombre de otra persona"><button onclick="addConsumptionRequester('${id}')">＋ Agregar</button></div></div><section class="orderPanel consumoOrder"><div class="orderTitle"><div><small>RONDA DE ${d.requester.toUpperCase()}</small><h3>Productos seleccionados</h3></div><div><small>Subtotal</small><strong>${COP(consumptionDraftTotal(id))}</strong></div></div><div class="orderCart">${consumptionDraftItems(id)}</div></section><button class="gold wide saveOrderTop" onclick="saveConsumptionOrder('${id}')" ${d.items.length?'':'disabled'}>💾 Guardar ronda · ${COP(consumptionDraftTotal(id))}</button><div class="notice compact">El inventario se descuenta únicamente al tocar <b>Guardar ronda</b>.</div><div class="quickActions consumoQuick"><button onclick="consumptionExtra('${id}')">➕ Extra personal / invitado</button><button onclick="startReturn('${id}')">↩️ Devolución</button><button onclick="viewAccount('${id}')">🧾 Ver cuenta</button></div><div class="catalogHead"><div><small>CATÁLOGO</small><h3>Agregar productos</h3></div><small>Toca para sumar</small></div><div class="chips">${categoryButtons(id)}</div><input class="search" id="prodSearch" placeholder="🔎 Buscar producto…" oninput="renderProducts('${id}')"><div id="productBox" class="products"></div><h3 class="manageSectionTitle">Rondas guardadas</h3><div class="card inner consumoHistory">${consumptionHistory(a)}</div><h3 class="manageSectionTitle">Resumen por persona</h3><div class="card inner">${consumptionBalances(a)}</div><div class="stickyActions"><button onclick="move('${id}')">⇄ Cambiar mesa</button><button onclick="viewAccount('${id}')">🧾 Ver cuenta</button><button class="gold" onclick="pay('${id}')">💰 Cobrar</button></div></div>`);renderProducts(id)}
function setConsumptionRequester(id,name){consumptionDraftFor(id).requester=name;openConsumption(id)}
function addConsumptionRequester(id){let n=(document.getElementById('newRequester')?.value||'').trim();if(!n)return alert('Escribe el nombre de la persona.');let a=t(id).account,existing=consumptionPeople(a).find(v=>playerKey(v)===playerKey(n));consumptionDraftFor(id).requester=existing||n;openConsumption(id)}
function consumptionDraftItems(id){let d=consumptionDraftFor(id);return d.items.length?d.items.map(i=>`<div class="orderLine"><div><b>${i.name}</b><small>${COP(i.price)} c/u</small></div><div class="qtyCtl"><button class="mini" onclick="consumptionQty('${id}','${i.id}',-1)">−</button><b>${i.qty}</b><button class="mini" onclick="consumptionQty('${id}','${i.id}',1)">+</button><strong>${COP(i.price*i.qty)}</strong></div></div>`).join(''):'<div class="emptyOrder">Toca productos del catálogo para preparar esta ronda.</div>'}
function consumptionQty(id,pid,delta){let d=consumptionDraftFor(id),it=d.items.find(x=>x.id===pid),p=catalog.find(x=>x.id===pid);if(!it&&delta>0&&p)d.items.push({id:pid,name:simpleName(p.name),price:p.price,cost:unitCost(p),qty:1});else if(it){it.qty+=delta;if(it.qty<=0)d.items=d.items.filter(x=>x!==it)}openConsumption(id)}
function saveConsumptionOrder(id){let a=t(id).account,d=consumptionDraftFor(id);if(!d.items.length)return alert('Agrega productos antes de guardar la ronda.');a.consumptionRounds=a.consumptionRounds||[];let requester=d.requester||'Cuenta general',r={id:Date.now()+Math.random(),requester,items:d.items.map(i=>({...i})),createdAt:new Date().toISOString(),status:'open'};for(const i of r.items){let p=catalog.find(x=>x.id===i.id);if(p)consumeInventory(p,i.qty)}a.consumptionRounds.push(r);a.history.push(stamp()+` · Ronda ${a.consumptionRounds.length} · ${requester}: ${COP(consumptionRoundTotal(r))}`);delete consumptionDraft[id];save('Ronda de consumo guardada');openConsumption(id)}
function consumptionHistory(a){let rs=a.consumptionRounds||[];return rs.length?[...rs].reverse().map(r=>`<div class="item consumoRound"><span><b>Ronda ${rs.indexOf(r)+1} · ${r.requester||'Cuenta general'}</b><br><small>${(r.items||[]).map(i=>`${i.name} ×${i.qty}`).join(' · ')}</small></span><b>${COP(consumptionRoundTotal(r))}</b></div>`).join(''):'<small>Aún no hay rondas guardadas.</small>'}
function consumptionBalances(a){let m={};for(const r of a.consumptionRounds||[]){let n=r.requester||'Cuenta general';m[n]=(m[n]||0)+consumptionRoundTotal(r)}for(const e of a.consumptionExtras||[]){let n=e.responsible||'Cuenta general';m[n]=(m[n]||0)+e.price*e.qty}return Object.keys(m).length?Object.entries(m).map(([n,v])=>`<div class="item"><span>👤 <b>${n}</b><br><small>Rondas + extras asociados</small></span><b>${COP(v)}</b></div>`).join(''):'<small>La cuenta todavía no tiene consumos guardados.</small>'}
let consumptionExtraDraft={};
function consumptionExtra(id,who=''){let a=t(id).account,people=consumptionPeople(a),d=consumptionExtraDraft[id]||(consumptionExtraDraft[id]={responsible:who||'',beneficiary:'Para sí mismo',items:[]});if(who)d.responsible=who;modal(`${modalNav("openConsumption('"+id+"')",'Mesa')}<h2>➕ Extra personal / invitado</h2><p class="notice compact">Úsalo cuando alguien pide algo adicional para sí mismo o le gasta un producto a una persona externa.</p><div class="extraPersonBox"><label>¿Quién se hace responsable del extra?</label><div class="personChips">${people.map(n=>`<button class="${d.responsible===n?'selectedPerson':''}" onclick="consumptionExtra('${id}','${esc(n)}')">👤 ${n}</button>`).join('')}</div><div class="field"><label>Responsable</label><input id="ceResponsible" value="${d.responsible||''}" placeholder="Ej. Yury"></div><div class="field"><label>¿Para quién es?</label><select id="ceBeneficiary"><option ${d.beneficiary==='Para sí mismo'?'selected':''}>Para sí mismo</option><option ${d.beneficiary==='Invitado externo'?'selected':''}>Invitado externo</option><option ${d.beneficiary==='Otra persona de la mesa'?'selected':''}>Otra persona de la mesa</option></select></div></div><div class="card inner extraCart">${d.items.length?d.items.map(e=>`<div class="orderLine"><div><b><span class="pill">EXTRA</span> ${e.name}</b></div><div class="qtyCtl"><button class="mini" onclick="consumptionExtraQty('${id}','${e.id}',-1)">−</button><b>${e.qty}</b><button class="mini" onclick="consumptionExtraQty('${id}','${e.id}',1)">+</button><strong>${COP(e.price*e.qty)}</strong></div></div>`).join(''):'<div class="emptyOrder">Aún no hay productos seleccionados.</div>'}</div><button class="gold wide" onclick="saveConsumptionExtra('${id}')" ${d.items.length?'':'disabled'}>💾 Guardar extra · ${COP(d.items.reduce((z,i)=>z+i.price*i.qty,0))}</button><div class="notice compact">El inventario se descuenta al guardar.</div><input class="search" id="ceSearch" placeholder="🔎 Buscar producto…" oninput="renderConsumptionExtraProducts('${id}')"><div id="ceProducts" class="products"></div>`);renderConsumptionExtraProducts(id)}
function renderConsumptionExtraProducts(id){let d=consumptionExtraDraft[id],q=(document.getElementById('ceSearch')?.value||'').toLowerCase(),box=document.getElementById('ceProducts');if(!box)return;box.innerHTML=catalog.filter(p=>p.price>0&&p.name.toLowerCase().includes(q)).slice(0,36).map(p=>{let qty=d.items.find(i=>i.id===p.id)?.qty||0;return `<div class="prod"><button onclick="consumptionExtraQty('${id}','${p.id}',1)"><b>${simpleName(p.name)}</b>${qty?`<span class="prodQty">×${qty}</span>`:''}<br><span>${COP(p.price)}</span></button></div>`}).join('')}
function consumptionExtraQty(id,pid,delta){let d=consumptionExtraDraft[id],p=catalog.find(x=>x.id===pid),it=d.items.find(x=>x.id===pid);if(!it&&delta>0)d.items.push({id:pid,name:simpleName(p.name),price:p.price,cost:unitCost(p),qty:1});else if(it){it.qty+=delta;if(it.qty<=0)d.items=d.items.filter(x=>x!==it)}consumptionExtra(id,d.responsible)}
function saveConsumptionExtra(id){let a=t(id).account,d=consumptionExtraDraft[id],responsible=(document.getElementById('ceResponsible')?.value||d.responsible||'').trim(),beneficiary=document.getElementById('ceBeneficiary')?.value||d.beneficiary;if(!responsible)return alert('Indica quién se hace responsable del extra.');if(!d.items.length)return;let existing=consumptionPeople(a).find(v=>playerKey(v)===playerKey(responsible));responsible=existing||responsible;a.consumptionExtras=a.consumptionExtras||[];for(const i of d.items){a.consumptionExtras.push({...i,responsible,beneficiary,kind:'consumptionExtra',ts:new Date().toISOString()});let p=catalog.find(x=>x.id===i.id);if(p)consumeInventory(p,i.qty)}a.history.push(stamp()+` · Extra de ${responsible} · ${beneficiary}: `+d.items.map(i=>`${i.name} ×${i.qty}`).join(', '));delete consumptionExtraDraft[id];save('Extra de consumo guardado');openConsumption(id)}
let activeCategory='Todos';function categoryButtons(id){let cats=['Todos','CERVEZAS','CUBETAZOS','MICHELADAS','GASEOSAS','LICORES','OTROS'];return cats.map(c=>`<button onclick="setCat('${id}','${c}')">${c==='Todos'?'⭐':c==='CERVEZAS'?'🍺':c==='CUBETAZOS'?'🪣':c==='MICHELADAS'?'🍹':c==='GASEOSAS'?'🥤':c==='LICORES'?'🥃':'🍬'} ${c}</button>`).join('')}
function setCat(id,c){activeCategory=c;renderProducts(id)}
function simpleName(n){return n.replace(/\s+[xX]\d+.*$/,'').replace(/\s+\d+\s*(cc|c|ml).*$/i,'').replace('Buweiser','Budweiser').trim()}
function catMatch(p,c){let z=p.category.toUpperCase(),n=p.name.toUpperCase();if(c==='Todos')return true;if(c==='CERVEZAS')return z.includes('CERVEZA');if(c==='CUBETAZOS')return z.includes('CUBET');if(c==='MICHELADAS')return z.includes('MICHEL')||n.includes('MICHEL');if(c==='GASEOSAS')return z.includes('GASEOSA')||z.includes('ENERG');if(c==='LICORES')return z.includes('AGUARD')||z.includes('LICOR')||z.includes('WHISK')||z.includes('RON');if(c==='OTROS')return !['CERVEZAS','CUBETAZOS','MICHELADAS','GASEOSAS','LICORES'].some(x=>catMatch(p,x));return true}
function renderProducts(id){let q=(prodSearch?.value||'').toLowerCase();let x=t(id),r=x?.account?.activeRound;let arr=catalog.filter(p=>p.price>0&&p.name.toLowerCase().includes(q)&&catMatch(p,activeCategory)).slice(0,36);productBox.innerHTML=arr.map(p=>{let qty=x?.type==='consumo'?(consumptionDraftFor(id).items.find(z=>z.id===p.id)?.qty||0):(r?.items?.find(z=>z.id===p.id)?.qty||0);return `<div class="prod"><button onclick="addProduct('${id}','${p.id}')"><b>${simpleName(p.name)}</b>${qty?`<span class="prodQty">×${qty}</span>`:''}<br><span>${COP(p.price)}</span></button></div>`}).join('')||'<p>No hay productos en esta categoría.</p>'}
function consumeInventory(p,qty=1){if(p.recipe?.length){for(const r of p.recipe)S.inventory[r.productId]=(S.inventory[r.productId]||0)-r.qty*qty}else if(p.type==='stock')S.inventory[p.id]=(S.inventory[p.id]||0)-qty}
function addProduct(id,pid){let x=t(id),a=x.account,p=catalog.find(z=>z.id===pid);if(x.type==='billar'){let r=a.activeRound||(a.activeRound=newRound());let it=r.items.find(z=>z.id===pid);it?it.qty++:r.items.push({id:pid,name:simpleName(p.name),price:p.price,cost:unitCost(p),qty:1,addedAt:new Date().toISOString(),extra:r.source.startsWith('Duplicada')});}else{let d=consumptionDraftFor(id),it=d.items.find(z=>z.id===pid);it?it.qty++:d.items.push({id:pid,name:simpleName(p.name),price:p.price,cost:unitCost(p),qty:1,addedAt:new Date().toISOString()});openConsumption(id);return}consumeInventory(p);a.history.push(stamp()+' · '+simpleName(p.name));save(`Producto ${simpleName(p.name)} en ${x.name}`);openAccount(id)}
function roundItems(r,id){return r.items.length?r.items.map(i=>`<div class="orderLine"><div><b>${i.name}</b><small>${COP(i.price)} c/u</small></div><div class="qtyCtl"><button class="mini" onclick="activeRoundQty('${id}','${i.id}',-1)">−</button><b>${i.qty}</b><button class="mini" onclick="activeRoundQty('${id}','${i.id}',1)">+</button><strong>${COP(i.price*i.qty)}</strong></div></div>`).join(''):'<div class="emptyOrder">Toca un producto del catálogo para agregarlo a esta ronda.</div>'}
function activeRoundQty(id,pid,delta){let x=t(id),a=x.account,r=a.activeRound;if(!r)return;let it=r.items.find(z=>z.id===pid),p=catalog.find(z=>z.id===pid);if(!it&&delta>0&&p){r.items.push({id:pid,name:simpleName(p.name),price:p.price,cost:unitCost(p),qty:1,addedAt:new Date().toISOString()});consumeInventory(p)}else if(it){if(delta>0){it.qty++;if(p)consumeInventory(p)}else{it.qty--;if(p)restoreInventory(p);if(it.qty<=0)r.items=r.items.filter(z=>z.id!==pid)}}a.history.push(stamp()+` · Ajuste ronda actual: ${p?simpleName(p.name):pid} ${delta>0?'+1':'-1'}`);save('Ajuste ronda actual');openBilliard(id)}
function looseItems(a){return a.loose.length?a.loose.map(i=>`<div class="item"><span>${i.name} × ${i.qty}</span><b>${COP(i.price*i.qty)}</b></div>`).join(''):'<small>Sin consumos.</small>'}
function returnRate(price){return price===5000?3000:(price===3000||price===4000)?2000:0}
function returnedQty(a,key){return(a.returns||[]).filter(x=>x.sourceKey===key).reduce((s,x)=>s+x.qty,0)}
function returnCandidates(a,type){let out=[];if(type==='consumo'){for(const r of a.consumptionRounds||[])for(const i of r.items||[])out.push({key:'consround:'+r.id+':'+i.id,id:i.id,name:i.name,price:i.price,cost:itemUnitCost(i),qty:i.qty,player:r.requester||null,source:'Ronda '+((a.consumptionRounds||[]).indexOf(r)+1)+' · '+(r.requester||'Cuenta general')});for(const e of a.consumptionExtras||[])out.push({key:'consextra:'+e.ts+':'+e.id,id:e.id,name:e.name,price:e.price,cost:itemUnitCost(e),qty:e.qty,player:e.responsible||null,source:'Extra · '+(e.beneficiary||'Personal')});for(const i of a.loose||[])out.push({key:'loose:'+i.id,id:i.id,name:i.name,price:i.price,cost:itemUnitCost(i),qty:i.qty,player:null,source:'Consumo anterior'})}else{for(const r of a.rounds||[])for(const i of r.items||[])out.push({key:'round:'+r.id+':'+i.id,id:i.id,name:i.name,price:i.price,cost:itemUnitCost(i),qty:i.qty,player:r.loser,source:'Partida '+((a.rounds||[]).indexOf(r)+1)});for(const e of a.playerExtras||[])out.push({key:'extra:'+e.player+':'+e.id,id:e.id,name:e.name,price:e.price,cost:itemUnitCost(e),qty:e.qty,player:e.player,source:'Extra de '+e.player})}return out.map(x=>({...x,available:Math.max(0,x.qty-returnedQty(a,x.key))})).filter(x=>x.available>0&&returnRate(x.price)>0)}
function startReturn(id){let x=t(id),a=x.account,c=returnCandidates(a,x.type);if(!c.length)return alert('No hay productos elegibles para devolución en esta cuenta.');modal(`${modalNav("openAccount('"+id+"')",'Orden')}<h2>↩️ Registrar devolución</h2><p class="notice compact">Productos de $3.000 o $4.000 se reciben a $2.000. Productos de $5.000 se reciben a $3.000. La diferencia se divide 50% mesera / 50% negocio y el producto vuelve al stock.</p><div class="field"><label>Producto</label><select id="retCandidate" onchange="returnPreview('${id}')">${c.map((z,i)=>`<option value="${i}">${z.name} · ${z.source}${z.player?' · '+z.player:''} · disp. ${z.available}</option>`).join('')}</select></div><div class="field"><label>Cantidad a devolver</label><input id="retQty" type="number" inputmode="numeric" min="1" value="1" oninput="returnPreview('${id}')"></div><div id="returnPreviewBox"></div><button class="gold wide" onclick="confirmReturn('${id}')">Confirmar devolución</button>`);returnPreview(id)}
function returnPreview(id){let x=t(id),c=returnCandidates(x.account,x.type),z=c[+(document.getElementById('retCandidate')?.value||0)],q=+(document.getElementById('retQty')?.value||0),b=document.getElementById('returnPreviewBox');if(!z||!b)return;let rate=returnRate(z.price),credit=rate*q,diff=(z.price-rate)*q,half=diff/2;b.innerHTML=`<div class="card inner"><div class="item"><span>Precio original</span><b>${COP(z.price)} c/u</b></div><div class="item"><span>Se recibe a</span><b>${COP(rate)} c/u</b></div><div class="item"><span>Cliente recibe / abono</span><b>${COP(credit)}</b></div><div class="item"><span>Diferencia</span><b>${COP(diff)}</b></div><div class="item"><span>50% mesera</span><b>${COP(half)}</b></div><div class="item"><span>50% negocio</span><b>${COP(half)}</b></div><div class="item"><span>Regresa a stock</span><b>${q} unidad(es)</b></div></div>${q>z.available?'<div class="notice">⚠️ La cantidad supera lo disponible para devolver.</div>':''}`}
function confirmReturn(id){let x=t(id),a=x.account,c=returnCandidates(a,x.type),z=c[+(retCandidate.value||0)],q=+retQty.value;if(!z||!Number.isInteger(q)||q<1||q>z.available)return alert('Cantidad de devolución no válida.');let rate=returnRate(z.price),credit=rate*q,diff=(z.price-rate)*q,half=diff/2,p=catalog.find(v=>v.id===z.id);if(p)restoreInventory(p,q);a.returns||=[];a.returns.push({id:'DEV-'+Date.now(),ts:new Date().toISOString(),sourceKey:z.key,source:z.source,productId:z.id,idProduct:z.id,name:z.name,price:z.price,cost:z.cost,qty:q,returnRate:rate,credit,difference:diff,waitressShare:half,businessShare:half,player:z.player||null,waitress:a.waitress});a.history.push(stamp()+` · Devolución ${z.name} ×${q}: cliente ${COP(credit)}, mesera ${COP(half)}, negocio ${COP(half)}`);S.inventoryMovements.push({id:Date.now(),ts:new Date().toISOString(),productId:z.id,product:z.name,type:'customer-return',qty:q,before:(S.inventory[z.id]||0)-q,after:S.inventory[z.id]||0,note:`${x.name} · ${z.player||a.group}`});save(`Devolución ${z.name} ×${q} en ${x.name}`);viewAccount(id)}
function returnsView(a){return(a.returns||[]).length?`<h3>↩️ Devoluciones</h3>${[...a.returns].reverse().map(d=>`<div class="item"><span><b>${d.name} ×${d.qty}</b>${d.player?` · ${d.player}`:''}<br><small>Recibido a ${COP(d.returnRate)} c/u · Cliente ${COP(d.credit)} · Mesera ${COP(d.waitressShare)} · Negocio ${COP(d.businessShare)}</small></span><b>− ${COP(d.credit)}</b></div>`).join('')}`:''}

function playerKey(n){return String(n||'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ')}
function knownPlayers(a){let raw=[...(a.players||[]),...(a.people||[]).filter(x=>x.role==='player').map(x=>x.name),...(a.rounds||[]).map(z=>z.loser)].filter(Boolean),out=[],seen=new Set();for(const n of raw){let k=playerKey(n);if(k&&!seen.has(k)){seen.add(k);out.push(n)}}return out}
function selectLoser(encoded){let n=decodeURIComponent(encoded),h=document.getElementById('loserName');if(h)h.value=n;document.querySelectorAll('.loserChoice').forEach(b=>b.classList.toggle('selected',b.dataset.player===encoded));document.getElementById('newLoserBox')?.classList.add('hidden')}
function showNewLoser(){document.querySelectorAll('.loserChoice').forEach(b=>b.classList.remove('selected'));let h=document.getElementById('loserName');if(h)h.value='';let c=document.getElementById('newLoserBox');if(c){c.classList.remove('hidden');setTimeout(()=>document.getElementById('newLoserName')?.focus(),30)}}
function useNewLoser(){let v=document.getElementById('newLoserName')?.value.trim();if(!v)return alert('Escribe el nombre del nuevo participante.');let h=document.getElementById('loserName');if(h)h.value=v;document.getElementById('newLoserBox')?.classList.add('hidden')}
function finishRound(id){let x=t(id),a=x.account,r=a.activeRound;if(!r)return;let known=knownPlayers(a);modal(`${modalNav("openBilliard('${id}')",'Partida')}<div class="finishRoundPanel"><h2>🏁 Terminar partida ${(a.rounds?.length||0)+1}</h2><p>Consumo: <b>${COP(roundConsumption(r))}</b><br>Chico: <b>${COP(GAME)}</b><br>Total a asignar: <b class="goldText">${COP(roundConsumption(r)+GAME)}</b></p><h3>¿Quién perdió esta partida?</h3>${known.length?`<div class="loserChoices">${known.map(n=>{let e=encodeURIComponent(n);return `<button type="button" class="loserChoice" data-player="${e}" onclick="selectLoser('${e}')">🎱 <b>${n}</b></button>`}).join('')}</div>`:`<p class="muted">Aún no hay jugadores registrados en esta mesa.</p>`}<button type="button" class="wide addLoser" onclick="showNewLoser()">➕ Otro participante</button><div id="newLoserBox" class="newLoserBox hidden"><div class="field"><label>Nombre del nuevo participante</label><input id="newLoserName" placeholder="Ej. Carlos" onkeydown="if(event.key==='Enter'){event.preventDefault();useNewLoser()}"></div><button type="button" onclick="useNewLoser()">✓ Usar este nombre</button></div><input id="loserName" type="hidden"><button class="finish wide" onclick="confirmFinish('${id}')">Confirmar y asignar cuenta</button><button class="wide" onclick="openBilliard('${id}')">Cancelar</button></div>`)}
function confirmFinish(id){let x=t(id),a=x.account,n=(document.getElementById('loserName')?.value||'').trim();if(!n)return alert('Selecciona quién perdió o agrega otro participante.');let existing=knownPlayers(a).find(v=>playerKey(v)===playerKey(n));if(existing)n=existing;let r=a.activeRound;r.status='closed';r.loser=n;r.gameFee=GAME;r.closedAt=new Date().toISOString();a.rounds.push(r);if(!(a.players||[]).some(v=>playerKey(v)===playerKey(n)))a.players=[...(a.players||[]),n];a.people=a.people||[];if(!a.people.some(x=>x.role==='player'&&playerKey(x.name)===playerKey(n)))a.people.push({name:n,role:'player'});a.history.push(stamp()+` · Partida ${a.rounds.length} asignada a ${n}: ${COP(roundConsumption(r)+GAME)}`);a.activeRound=newRound('Nueva partida');save(`Partida ${a.rounds.length} de ${x.name} asignada a ${n}`);openBilliard(id)}
function duplicatePreview(id){let a=t(id).account,last=a.rounds[a.rounds.length-1];if(!last)return;modal(`${modalNav("openBilliard('${id}')",'Partida')}<h2>🔁 Duplicar partida anterior</h2><p>Se copiará únicamente el pedido. <b>No se copiará el perdedor.</b></p><div class="card inner">${last.items.map(i=>`<div class="item"><span>${i.name} × ${i.qty}</span><b>${COP(i.price*i.qty)}</b></div>`).join('')||'Sin productos'}</div><div class="total">Pedido: ${COP(roundConsumption(last))}</div><p class="notice compact">Al confirmar, estas unidades se descuentan del inventario como un nuevo despacho. Después podrás agregar extras.</p><button class="gold wide" onclick="confirmDuplicate('${id}')">Duplicar pedido</button><button class="wide" onclick="openBilliard('${id}')">Cancelar</button>`)}
function confirmDuplicate(id){let a=t(id).account,last=a.rounds[a.rounds.length-1];if(!last)return;let items=last.items.map(i=>{let p=catalog.find(z=>z.id===i.id);return {...i,cost:unitCost(p),addedAt:new Date().toISOString(),extra:false}});for(const i of items){let p=catalog.find(z=>z.id===i.id);if(p)consumeInventory(p,i.qty)}a.activeRound=newRound(`Duplicada de partida ${a.rounds.length}`,items);a.history.push(stamp()+` · Pedido de partida ${a.rounds.length} duplicado`);save(`Partida duplicada en ${t(id).name}`);openBilliard(id)}
function playerMap(a){let m={};for(const r of a.rounds||[])m[r.loser]=(m[r.loser]||0)+GAME+roundConsumption(r);for(const e of a.playerExtras||[])m[e.player]=(m[e.player]||0)+e.price*e.qty;for(const p of a.payments||[])m[p.player]=(m[p.player]||0)-p.amount;for(const d of a.returns||[])if(d.player)m[d.player]=(m[d.player]||0)-d.credit;return m}
function playerBreakdown(a,name){let rounds=(a.rounds||[]).filter(r=>r.loser===name),roundsTotal=rounds.reduce((z,r)=>z+(r.gameFee||GAME)+roundConsumption(r),0),extras=(a.playerExtras||[]).filter(e=>e.player===name&&e.kind==='extraPersonal'),extrasTotal=extras.reduce((z,e)=>z+e.price*e.qty,0),returns=(a.returns||[]).filter(d=>d.player===name).reduce((z,d)=>z+d.credit,0),paid=(a.payments||[]).filter(p=>p.player===name).reduce((z,p)=>z+p.amount,0),total=Math.max(0,roundsTotal+extrasTotal-returns-paid);return{rounds,roundsTotal,extras,extrasTotal,returns,paid,total}}
function playerBalances(a,id){let m=playerMap(a);return Object.keys(m).length?Object.entries(m).sort((a,b)=>b[1]-a[1]).map(([n,v])=>{let b=playerBreakdown(a,n);return `<div class="item playerSummary"><button class="playerLink" onclick="playerAccount('${id||''}','${esc(n)}')">👤 <b>${n}</b><small>Rondas ${COP(b.roundsTotal)}${b.extrasTotal?` · 🟡 Extras ${COP(b.extrasTotal)}`:''}</small></button><div><small>TOTAL PENDIENTE</small><b>${COP(v)}</b></div></div>`}).join(''):'<small>Aún no hay cuentas asignadas.</small>'}
function esc(s){return String(s).replace(/'/g,"\\'")}
function roundHistory(a,id){return(a.rounds||[]).length?[...a.rounds].reverse().map(r=>`<div class="item"><span>Partida ${a.rounds.indexOf(r)+1} · <b>${r.loser}</b><br><small>${r.items.map(x=>`${x.name} ×${x.qty}`).join(' · ')||'Sin consumo'}</small></span><span><b>${COP(GAME+roundConsumption(r))}</b>${id?`<br><button class="mini" onclick="editRound('${id}',${a.rounds.indexOf(r)})">✏️ Editar</button>`:''}</span></div>`).join(''):'<small>Sin partidas finalizadas.</small>'}
function viewAccount(id){let x=t(id),a=x.account;modal(`${modalNav("openAccount('"+id+"')",'Orden')}<h2>🧾 Cuenta · ${x.name}</h2><p>${a.group} · Mesera: ${a.waitress}</p>${x.type==='billar'?`<h3>Por jugador</h3>${playerBalances(a,id)}<button class="wide" onclick="extraPlayer('${id}')">➕ Agregar extra a jugador</button><h3>Partidas</h3>${roundHistory(a,id)}${pendingTotal(a)?`<div class="notice">Hay una ronda en curso con ${COP(pendingTotal(a))} de consumo aún sin perdedor.</div>`:''}`:`<h3>Rondas</h3>${consumptionHistory(a)}<h3>Resumen asociado</h3>${consumptionBalances(a)}${(a.consumptionExtras||[]).length?`<h3>Extras</h3>${(a.consumptionExtras||[]).map(e=>`<div class="item"><span><b>EXTRA · ${e.responsible}</b><br><small>${e.beneficiary} · ${e.name} ×${e.qty}</small></span><b>${COP(e.price*e.qty)}</b></div>`).join('')}`:''}`}${returnsView(a)}<button class="wide" onclick="startReturn('${id}')">↩️ Registrar devolución</button><div class="total">Saldo pendiente: ${COP(closedTotal(a))}</div><button class="gold wide" onclick="pay('${id}')">💰 Cobrar${x.type==='billar'?' por jugador':''}</button><button class="wide" onclick="openAccount('${id}')">Volver</button>`)}
function peopleList(a){let out=[];for(const n of a.players||[])if(n&&!out.some(x=>x.name===n))out.push({name:n,role:'player'});for(const x of a.people||[])if(x?.name&&!out.some(y=>y.name===x.name))out.push(x);for(const e of a.playerExtras||[])if(e.player&&!out.some(x=>x.name===e.player))out.push({name:e.player,role:'companion'});return out}
let extraDraft={};
function extraDraftKey(id,name){return id+'||'+name}
function extraDraftItems(id,name){return extraDraft[extraDraftKey(id,name)]||[]}
function extraDraftTotal(id,name){return extraDraftItems(id,name).reduce((z,e)=>z+e.price*e.qty,0)}
function extraPlayer(id,selected=''){let a=t(id).account,people=peopleList(a),draft=selected?extraDraftItems(id,selected):[];modal(`${modalNav("openBilliard('"+id+"')",'Partida')}<h2>➕ Consumo extra personal</h2><p>Todo producto agregado aquí queda identificado como <b>EXTRA</b> y separado del consumo de las partidas cerradas.</p><div class="extraPersonBox"><label>¿Quién pidió el extra?</label><div class="personChips">${people.map(x=>`<button class="${selected===x.name?'selectedPerson':''}" onclick="extraPlayer('${id}','${esc(x.name)}')">${x.role==='player'?'🎱':'👤'} ${x.name}</button>`).join('')}</div><button class="wide" onclick="newPerson('${id}')">＋ Agregar persona / acompañante</button></div>${selected?`<div class="extraSelected"><b>Cuenta de ${selected}</b><span>${COP(playerMap(a)[selected]||0)}</span></div><h3>🟡 EXTRAS guardados</h3><div class="card inner extraCart">${extraItems(a,id,selected)}</div><h3>🛒 Pedido por guardar</h3><div class="card inner extraCart">${draft.length?draft.map(e=>`<div class="orderLine"><div><b><span class="pill">EXTRA</span> ${e.name}</b><small>${COP(e.price)} c/u</small></div><div class="qtyCtl"><button class="mini" onclick="changeDraftExtra('${id}','${esc(selected)}','${e.id}',-1)">−</button><b>${e.qty}</b><button class="mini" onclick="changeDraftExtra('${id}','${esc(selected)}','${e.id}',1)">+</button><strong>${COP(e.price*e.qty)}</strong></div></div>`).join(''):'<div class="emptyOrder">Aún no has agregado productos para guardar.</div>'}</div><button class="gold wide saveExtraBtn" onclick="savePlayerExtras('${id}','${esc(selected)}')" ${draft.length?'':'disabled'}>💾 Guardar extras · ${COP(extraDraftTotal(id,selected))}</button><div class="notice compact">Los productos del pedido se descuentan del inventario únicamente al tocar <b>Guardar extras</b>.</div><input class="search" id="extraSearch" placeholder="🔎 Buscar cualquier producto…" oninput="renderExtraProducts('${id}','${esc(selected)}')"><div id="extraBox" class="products"></div>`:`<div class="notice compact">Selecciona una persona o agrega un acompañante para empezar.</div>`}`);if(selected)renderExtraProducts(id,selected)}
function newPerson(id){modal(`${modalNav("extraPlayer('"+id+"')",'Extras')}<h2>👤 Agregar persona</h2><div class="field"><label>Nombre</label><input id="personName" placeholder="Ej. Esposa de Juan"></div><div class="field"><label>Tipo</label><select id="personRole"><option value="companion">Acompañante (no participa como perdedor)</option><option value="player">Jugador</option></select></div><button class="gold wide" onclick="savePerson('${id}')">Agregar y continuar</button>`)}
function savePerson(id){let a=t(id).account,n=personName.value.trim(),role=personRole.value;if(!n)return alert('Escribe el nombre.');a.people||=[];if(!a.people.some(x=>x.name===n))a.people.push({name:n,role});if(role==='player'&&!a.players.includes(n))a.players.push(n);a.history.push(stamp()+` · ${role==='player'?'Jugador':'Acompañante'} agregado: ${n}`);save('Persona agregada');extraPlayer(id,n)}
function extraItems(a,id,name){let xs=(a.playerExtras||[]).filter(e=>e.player===name);return xs.length?xs.map(e=>`<div class="orderLine"><div><b><span class="pill">EXTRA</span> ${e.name}</b><small>${COP(e.price)} c/u${e.ts?` · ${new Date(e.ts).toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'})}`:''}</small></div><div class="qtyCtl"><button class="mini" onclick="changeExtraQty('${id}','${esc(name)}','${e.id}',-1)">−</button><b>${e.qty}</b><button class="mini" onclick="changeExtraQty('${id}','${esc(name)}','${e.id}',1)">+</button><strong>${COP(e.price*e.qty)}</strong></div></div>`).join(''):'<div class="emptyOrder">Sin extras guardados.</div>'}
function renderExtraProducts(id,name){let q=(document.getElementById('extraSearch')?.value||'').toLowerCase(),box=document.getElementById('extraBox'),draft=extraDraftItems(id,name);if(!box)return;box.innerHTML=catalog.filter(p=>p.price>0&&p.name.toLowerCase().includes(q)).slice(0,40).map(p=>{let d=draft.find(x=>x.id===p.id),qty=d?.qty||0;return `<div class="prod ${qty?'extraProdSelected':''}"><button onclick="addPlayerExtra('${id}','${p.id}','${esc(name)}')">${qty?`<span class="prodQty">×${qty}</span>`:''}<b>${simpleName(p.name)}</b><br>${COP(p.price)}<br><small>${qty?'✓ Seleccionado · EXTRA personal':'＋ Añadir al pedido'}</small></button></div>`}).join('')}
function addPlayerExtra(id,pid,name){let p=catalog.find(x=>x.id===pid);if(!p)return;let pos=document.getElementById('sheet')?.scrollTop||0,k=extraDraftKey(id,name),xs=extraDraft[k]||(extraDraft[k]=[]),it=xs.find(x=>x.id===pid);it?it.qty++:xs.push({id:pid,name:simpleName(p.name),price:p.price,cost:unitCost(p),qty:1});extraPlayer(id,name);requestAnimationFrame(()=>{let sh=document.getElementById('sheet');if(sh)sh.scrollTop=pos})}
function changeDraftExtra(id,name,pid,delta){let k=extraDraftKey(id,name),xs=extraDraft[k]||[],it=xs.find(x=>x.id===pid);if(!it)return;it.qty+=delta;if(it.qty<=0)xs.splice(xs.indexOf(it),1);extraDraft[k]=xs;extraPlayer(id,name)}
function savePlayerExtras(id,name){let a=t(id).account,k=extraDraftKey(id,name),xs=extraDraft[k]||[];if(!xs.length)return alert('No hay productos por guardar.');a.playerExtras||=[];for(const d of xs){let p=catalog.find(x=>x.id===d.id),it=a.playerExtras.find(x=>x.player===name&&x.id===d.id);if(it){it.qty+=d.qty;it.ts=new Date().toISOString()}else a.playerExtras.push({...d,player:name,ts:new Date().toISOString(),kind:'extraPersonal'});if(p)consumeInventory(p,d.qty)}a.history.push(stamp()+` · EXTRAS guardados para ${name}: `+xs.map(e=>`${e.name} ×${e.qty}`).join(', '));delete extraDraft[k];save(`Extras guardados de ${name}`);alert('✓ Extras guardados en la cuenta de '+name);extraPlayer(id,name)}
function changeExtraQty(id,name,pid,delta){let a=t(id).account,it=(a.playerExtras||[]).find(x=>x.player===name&&x.id===pid),p=catalog.find(x=>x.id===pid);if(delta>0){if(!it)return;it.qty++;it.ts=new Date().toISOString();if(p)consumeInventory(p)}else if(it){it.qty--;if(p)restoreInventory(p);if(it.qty<=0)a.playerExtras=a.playerExtras.filter(x=>x!==it)}a.history.push(stamp()+` · Ajuste EXTRA ${name}: ${delta>0?'+1':'-1'} ${p?simpleName(p.name):pid}`);save('Ajuste extra personal');extraPlayer(id,name)}
function playerAccount(id,name){let a=t(id).account,b=playerBreakdown(a,name),pays=(a.payments||[]).filter(p=>p.player===name);modal(`${modalNav("viewAccount('"+id+"')",'Cuenta')}<h2>👤 ${name}</h2><div class="total accountGrandTotal"><small>TOTAL PENDIENTE</small>${COP(b.total)}</div><div class="accountBreakdown"><div><span>🎱 Rondas perdidas + chicos</span><b>${COP(b.roundsTotal)}</b></div><div><span>🟡 Consumo adicional personal</span><b>${COP(b.extrasTotal)}</b></div>${b.returns?`<div><span>↩️ Devoluciones</span><b>− ${COP(b.returns)}</b></div>`:''}${b.paid?`<div><span>✓ Pagos realizados</span><b>− ${COP(b.paid)}</b></div>`:''}</div><h3>🎱 Rondas perdidas</h3>${b.rounds.length?b.rounds.map(r=>{let i=(a.rounds||[]).indexOf(r);return `<div class="item"><span>Partida ${i+1}<br><small>${r.items.map(x=>`${x.name} ×${x.qty}`).join(' · ')||'Sin consumo'} · Chico ${COP(r.gameFee||GAME)}</small></span><span><b>${COP((r.gameFee||GAME)+roundConsumption(r))}</b><br><button class="mini" onclick="editRound('${id}',${i})">✏️ Editar</button></span></div>`}).join(''):'<small>Ninguna.</small>'}<h3>🟡 CONSUMO ADICIONAL PERSONAL</h3>${b.extras.length?b.extras.map(e=>`<div class="item extraPersonalLine"><span><b><span class="pill">EXTRA PERSONAL</span> ${e.name}</b><br><small>${COP(e.price)} c/u · ${e.qty} unidad${e.qty===1?'':'es'}</small></span><span><b>${COP(e.price*e.qty)}</b><br><button class="mini" onclick="removeExtra('${id}','${esc(name)}','${e.id}')">− Quitar 1</button></span></div>`).join(''):'<div class="emptyOrder">Sin consumos adicionales personales.</div>'}<button class="wide" onclick="extraPlayer('${id}','${esc(name)}')">➕ Agregar consumo adicional a ${name}</button><div class="total accountGrandTotal"><small>TOTAL A PAGAR DE ${name.toUpperCase()}</small>${COP(b.total)}</div><h3>Pagos</h3>${pays.length?pays.map(p=>`<div class="item"><span>${p.method}<br><small>${new Date(p.ts).toLocaleString('es-CO')}</small></span><b>− ${COP(p.amount)}</b></div>`).join(''):'<small>Sin pagos.</small>'}${b.total>0?`<button class="gold wide" onclick="payPlayer('${id}','${esc(name)}')">💰 Cobrar total de ${name} · ${COP(b.total)}</button>`:''}`)}
function removeExtra(id,name,pid){let a=t(id).account,i=a.playerExtras.findIndex(x=>x.player===name&&x.id===pid);if(i<0)return;let e=a.playerExtras[i],p=catalog.find(x=>x.id===pid);e.qty--;if(p)restoreInventory(p);if(e.qty<=0)a.playerExtras.splice(i,1);a.history.push(stamp()+` · Ajuste extra de ${name}: -1 ${e.name}`);save('Ajuste extra');playerAccount(id,name)}
function editRound(id,idx){let a=t(id).account,r=a.rounds[idx],known=[...new Set([...(a.players||[]),...a.rounds.map(x=>x.loser)])],name=r.loser,draft=extraDraftItems(id,name);modal(`${modalNav("viewAccount('"+id+"')",'Cuenta')}<h2>✏️ Editar partida ${idx+1}</h2><div class="field"><label>Perdedor</label><input id="editLoser" list="editPlayers" value="${r.loser}"><datalist id="editPlayers">${known.map(n=>`<option value="${n}">`).join('')}</datalist></div><section class="orderPanel"><div class="orderTitle"><div><small>PRODUCTOS DE LA RONDA CERRADA</small><h3>🧾 Partida ${idx+1}</h3></div><div><small>Consumo</small><strong>${COP(roundConsumption(r))}</strong></div></div><div class="orderCart">${r.items.length?r.items.map((it,j)=>`<div class="orderLine"><div><b>${it.name}</b><small>${COP(it.price)} c/u</small></div><div class="qtyCtl"><button class="mini" onclick="roundQty('${id}',${idx},${j},-1)">−</button><b>${it.qty}</b><button class="mini" onclick="roundQty('${id}',${idx},${j},1)">+</button><strong>${COP(it.price*it.qty)}</strong></div></div>`).join(''):'<div class="emptyOrder">Sin productos en esta partida.</div>'}</div></section><button class="gold wide saveOrderTop" onclick="saveRoundEdit('${id}',${idx})">💾 Guardar correcciones de la ronda</button><p class="notice compact">Esta partida ya está cerrada. Los botones +/− de arriba sirven únicamente para <b>corregir productos que ya pertenecían a la ronda</b>. Todo producto nuevo que ${name} pida después se guarda separado como <b>EXTRA personal</b>.</p><h3>🟡 Consumo adicional personal de ${name}</h3><div class="card inner extraCart">${draft.length?draft.map(e=>`<div class="orderLine"><div><b><span class="pill">EXTRA</span> ${e.name}</b><small>${COP(e.price)} c/u</small></div><div class="qtyCtl"><button class="mini" onclick="changeClosedRoundExtraDraft('${id}',${idx},'${e.id}',-1)">−</button><b>${e.qty}</b><button class="mini" onclick="changeClosedRoundExtraDraft('${id}',${idx},'${e.id}',1)">+</button><strong>${COP(e.price*e.qty)}</strong></div></div>`).join(''):'<div class="emptyOrder">Aún no has agregado productos adicionales para <b>${name}</b>.</div>'}</div><button class="gold wide saveExtraBtn" onclick="saveClosedRoundExtras('${id}',${idx})" ${draft.length?'':'disabled'}>💾 Guardar consumo adicional · ${COP(extraDraftTotal(id,name))}</button><p class="muted">Busca un producto nuevo. Se agregará al pedido personal de <b>${name}</b>, no a la partida cerrada.</p><input class="search" id="editRoundSearch" placeholder="🔎 Buscar producto adicional…" oninput="renderRoundEditProducts('${id}',${idx})"><div id="editRoundProducts" class="products"></div>`);renderRoundEditProducts(id,idx)}
function renderRoundEditProducts(id,idx){let a=t(id).account,r=a.rounds[idx],q=(document.getElementById('editRoundSearch')?.value||'').toLowerCase(),box=document.getElementById('editRoundProducts'),draft=extraDraftItems(id,r.loser);if(!box)return;box.innerHTML=catalog.filter(p=>p.price>0&&p.name.toLowerCase().includes(q)).slice(0,50).map(p=>{let d=draft.find(x=>x.id===p.id),qty=d?.qty||0;return `<div class="prod ${qty?'extraProdSelected':''}"><button onclick="addClosedRoundExtraDraft('${id}',${idx},'${p.id}')">${qty?`<span class="prodQty">×${qty}</span>`:''}<b>＋ ${simpleName(p.name)}</b><br>${COP(p.price)}<br><small>${qty?'✓ Seleccionado · ':''}EXTRA personal · ${r.loser}</small></button></div>`}).join('')}
function addClosedRoundExtraDraft(id,idx,pid){let a=t(id).account,r=a.rounds[idx],name=r.loser,p=catalog.find(x=>x.id===pid);if(!p)return;let pos=document.getElementById('sheet')?.scrollTop||0,k=extraDraftKey(id,name),xs=extraDraft[k]||(extraDraft[k]=[]),it=xs.find(x=>x.id===pid);it?it.qty++:xs.push({id:p.id,name:simpleName(p.name),price:p.price,cost:unitCost(p),qty:1,kind:'extraPersonal'});editRound(id,idx);requestAnimationFrame(()=>{let sh=document.getElementById('sheet');if(sh)sh.scrollTop=pos})}
function changeClosedRoundExtraDraft(id,idx,pid,delta){let a=t(id).account,name=a.rounds[idx].loser,k=extraDraftKey(id,name),xs=extraDraft[k]||[],it=xs.find(x=>x.id===pid);if(!it)return;it.qty+=delta;if(it.qty<=0)xs.splice(xs.indexOf(it),1);extraDraft[k]=xs;editRound(id,idx)}
function saveClosedRoundExtras(id,idx){let a=t(id).account,name=a.rounds[idx].loser,k=extraDraftKey(id,name),xs=extraDraft[k]||[];if(!xs.length)return alert('No hay consumo adicional por guardar.');a.playerExtras||=[];for(const d of xs){let p=catalog.find(x=>x.id===d.id),it=a.playerExtras.find(x=>x.player===name&&x.id===d.id&&x.kind==='extraPersonal');if(it){it.qty+=d.qty;it.ts=new Date().toISOString()}else a.playerExtras.push({...d,player:name,ts:new Date().toISOString(),kind:'extraPersonal',sourceRoundId:a.rounds[idx].id,sourceRoundNumber:idx+1});if(p)consumeInventory(p,d.qty)}a.history.push(stamp()+` · Consumo adicional personal de ${name} después de partida ${idx+1}: `+xs.map(e=>`${e.name} ×${e.qty}`).join(', '));delete extraDraft[k];save(`Consumo adicional personal guardado de ${name}`);alert('✓ Consumo adicional personal guardado para '+name);playerAccount(id,name)}
function saveRoundEdit(id,idx){let a=t(id).account,r=a.rounds[idx],n=editLoser.value.trim();if(!n)return alert('Indica el perdedor.');let old=r.loser;r.loser=n;a.players=[...new Set([...(a.players||[]),n])];a.people=a.people||[];if(!a.people.some(x=>x.name===n))a.people.push({name:n,role:'player'});a.history.push(stamp()+` · Partida ${idx+1}: perdedor cambiado ${old} → ${n}`);save('Corrección de partida');viewAccount(id)}
function roundQty(id,idx,j,delta){let a=t(id).account,r=a.rounds[idx],it=r.items[j],p=catalog.find(x=>x.id===it.id);if(delta<0&&it.qty<=0)return;if(delta>0){it.qty++;if(p)consumeInventory(p)}else{it.qty--;if(p)restoreInventory(p);if(it.qty<=0)r.items.splice(j,1)}a.history.push(stamp()+` · Ajuste partida ${idx+1}: ${it.name} ${delta>0?'+1':'-1'}`);save('Ajuste producto partida');editRound(id,idx)}
function pay(id){let x=t(id),a=x.account;if(x.type==='billar'){let m=playerMap(a),names=Object.keys(m).filter(n=>m[n]>0),total=closedTotal(a);if(!names.length)return alert('No hay saldos pendientes.');modal(`${modalNav("openAccount('"+id+"')",'Orden')}<h2>💰 Cobrar</h2><p>Selecciona un jugador para cobrar su saldo individual o usa <b>Pago total</b> si una sola persona paga toda la cuenta.</p><button class="gold wide totalPayBtn" onclick="payWhole('${id}',${total})">💳 Pago total · ${COP(total)}</button><div class="payDivider"><span>O cobrar por jugador</span></div>${names.map(n=>`<button class="playerPay" onclick="payPlayer('${id}','${esc(n)}')"><span>👤 ${n}</span><b>${COP(m[n])}</b></button>`).join('')}<div class="total">Saldo total: ${COP(total)}</div>`);return}let v=closedTotal(a);if(v<=0)return alert('No hay saldo pendiente.');let people=consumptionPeople(a);modal(`${modalNav("openAccount('"+id+"')",'Orden')}<h2>💰 Cobrar consumo</h2><p>La forma de pago puede ser diferente a quien pidió las rondas. Elige cómo desean organizar el pago.</p><button class="gold wide totalPayBtn" onclick="payWhole('${id}',${v})">💳 Una persona paga todo · ${COP(v)}</button><div class="payDivider"><span>O hacer un abono / pago parcial</span></div><div class="field"><label>Valor que van a pagar ahora</label><input id="consPayAmount" type="number" inputmode="numeric" min="1" max="${v}" placeholder="Ej. 50000"></div><button class="wide" onclick="payConsumptionAmount('${id}')">💵 Cobrar valor personalizado</button>${people.length?`<div class="notice compact">Rondas identificadas por: <b>${people.join(' · ')}</b>. Esto sirve como referencia; el pago final puede negociarse libremente.</div>`:''}<div class="total">Saldo mesa: ${COP(v)}</div>`)}
function payConsumptionAmount(id){let v=+(document.getElementById('consPayAmount')?.value||0),max=closedTotal(t(id).account);if(!v||v<=0||v>max)return alert('Indica un valor válido hasta '+COP(max)+'.');modal(`${modalNav("pay('"+id+"')",'Cobro')}<h2>💵 Pago parcial</h2><div class="total">${COP(v)}</div><div class="field"><label>Método</label><select id="method" onchange="payFields(${v})"><option>Efectivo</option><option>Transferencia</option><option>Mixto</option></select></div><div id="payFields"></div><div class="field"><label>Referencia / quién paga (opcional)</label><input id="reference" placeholder="Ej. Juan paga su parte"></div><button class="gold wide" onclick="confirmConsumptionPartial('${id}',${v})">Confirmar pago parcial</button>`);payFields(v)}
function confirmConsumptionPartial(id,v){let x=t(id),a=x.account,parts=paymentParts(v),err=validatePayment(v,parts);if(err)return alert(err);let before=closedTotal(a),ratio=before?Math.min(1,v/before):0,cogs=Math.round(remainingCOGS(a)*ratio),payrec={id:'PAY-'+Date.now(),ts:new Date().toISOString(),amount:v,method:parts.m,ref:reference.value,cogs};a.payments=a.payments||[];a.payments.push(payrec);let sale={id:'LH-'+String(S.sales.length+1).padStart(6,'0'),ts:new Date().toISOString(),table:x.name,group:a.group,waitress:a.waitress,total:v,cash:parts.c,transfer:parts.tr,cashReceived:parts.received,change:parts.change,method:parts.m,ref:reference.value,cogs,grossProfit:v-cogs,account:JSON.parse(JSON.stringify(a)),partial:true};S.sales.push(sale);a.history.push(stamp()+` · Pago parcial ${COP(v)} · saldo ${COP(closedTotal(a))}`);save(`Pago parcial ${sale.id} ${x.name}`);receipt(sale)}
function payPlayer(id,name){let a=t(id).account,v=playerMap(a)[name]||0;if(v<=0)return;modal(`${modalNav("viewAccount('"+id+"')",'Cuenta')}<h2>💰 Cobrar a ${name}</h2><div class="total">${COP(v)}</div><div class="field"><label>Método</label><select id="method" onchange="payFields(${v})"><option>Efectivo</option><option>Transferencia</option><option>Mixto</option></select></div><div id="payFields"></div><div class="field"><label>Referencia / observación</label><input id="reference"></div><button class="gold wide" onclick="confirmPlayerPay('${id}','${esc(name)}',${v})">Confirmar pago</button>`);payFields(v)}
function payWhole(id,v){modal(`${modalNav("openAccount('"+id+"')",'Orden')}<h2>💰 Cobrar</h2><div class="total">${COP(v)}</div><div class="field"><label>Método</label><select id="method" onchange="payFields(${v})"><option>Efectivo</option><option>Transferencia</option><option>Mixto</option></select></div><div id="payFields"></div><div class="field"><label>Referencia</label><input id="reference"></div><button class="gold wide" onclick="confirmPay('${id}',${v})">Confirmar pago</button>`);payFields(v)}
function payFields(v){let el=document.getElementById('payFields'),m=document.getElementById('method').value;if(m==='Efectivo'){el.innerHTML=`<div class="field"><label>Efectivo recibido</label><input id="cashReceived" type="text" inputmode="numeric" placeholder="Ej. 100.000" oninput="formatMoneyInput(this);updateChange(${v})"></div><div id="changeBox" class="notice">Ingresa el efectivo recibido para calcular las vueltas.</div>`}else if(m==='Transferencia'){el.innerHTML=`<div class="notice">Transferencia a registrar: <b>${COP(v)}</b></div>`}else{el.innerHTML=`<div class="field"><label>Valor por transferencia</label><input id="transIn" type="number" inputmode="numeric" min="0" max="${v}" value="0" oninput="updateMixed(${v})"></div><div class="field"><label>Efectivo recibido</label><input id="cashReceived" type="text" inputmode="numeric" value="0" oninput="formatMoneyInput(this);updateMixed(${v})"></div><div id="changeBox" class="notice">Indica cuánto se transfiere y cuánto efectivo entrega el cliente.</div>`}}
function moneyValue(el){return +(String(el?.value||'0').replace(/\D/g,''))}function formatMoneyInput(el){let n=moneyValue(el);el.value=n?new Intl.NumberFormat('es-CO').format(n):''}function updateChange(v){let r=moneyValue(document.getElementById('cashReceived')),b=document.getElementById('changeBox');if(!b)return;let d=r-v;b.innerHTML=r<=0?'Ingresa el efectivo recibido para calcular las vueltas.':d<0?`⚠️ Faltan <b>${COP(-d)}</b>`:d===0?'✅ <b>Pago exacto</b>':`💵 Cambio a devolver: <b>${COP(d)}</b>`}
function updateMixed(v){let tr=+(document.getElementById('transIn')?.value||0),r=moneyValue(document.getElementById('cashReceived')),b=document.getElementById('changeBox');if(!b)return;if(tr<0||tr>v){b.innerHTML='⚠️ La transferencia no puede superar el total.';return}let due=v-tr,d=r-d;b.innerHTML=`Transferencia: <b>${COP(tr)}</b> · Efectivo a cubrir: <b>${COP(due)}</b><br>`+(d<0?`⚠️ Faltan <b>${COP(-d)}</b> en efectivo`:d===0?'✅ <b>Pago exacto</b>':`💵 Cambio a devolver: <b>${COP(d)}</b>`)}
function paymentParts(v){let m=method.value;if(m==='Transferencia')return{m,c:0,tr:v,received:0,change:0};let r=moneyValue(document.getElementById('cashReceived'));if(m==='Efectivo')return{m,c:v,tr:0,received:r,change:r-v};let tr=+(document.getElementById('transIn')?.value||0),c=v-tr;return{m,c,tr,received:r,change:r-c}}
function validatePayment(v,parts){if(parts.tr<0||parts.c<0||parts.c+parts.tr!==v)return'Los pagos deben sumar el total.';if((parts.m==='Efectivo'||parts.m==='Mixto')&&parts.received<parts.c)return`Faltan ${COP(parts.c-parts.received)} en efectivo.`;return''}
function confirmPlayerPay(id,name,v){let x=t(id),a=x.account,parts=paymentParts(v),err=validatePayment(v,parts);if(err)return alert(err);let{m,c,tr,received,change}=parts;let cogs=accountCOGS(a,name),p={id:'LH-'+String(S.sales.length+1).padStart(6,'0'),ts:new Date().toISOString(),table:x.name,group:a.group,waitress:a.waitress,player:name,total:v,amount:v,cash:c,transfer:tr,cashReceived:received,change,method:m,ref:reference.value,cogs,grossProfit:v-cogs,account:JSON.parse(JSON.stringify(a))};a.payments||=[];a.payments.push({player:name,amount:v,cash:c,transfer:tr,cashReceived:received,change,method:m,ref:reference.value,ts:p.ts,cogs});S.sales.push(p);a.history.push(stamp()+` · Pago de ${name}: ${COP(v)} (${m})${change>0?' · Cambio '+COP(change):''}`);save(`Pago ${name}`);if(closedTotal(a)<=0&&!pendingTotal(a)){if(confirm('Todos los saldos están pagados. ¿Cerrar y liberar la mesa?'))x.account=null;save('Mesa liberada')}receipt(p)}
function confirmPay(id,v){let x=t(id),parts=paymentParts(v),err=validatePayment(v,parts);if(err)return alert(err);let{m,c,tr,received,change}=parts;let cogs=remainingCOGS(x.account),sale={id:'LH-'+String(S.sales.length+1).padStart(6,'0'),ts:new Date().toISOString(),table:x.name,group:x.account.group,waitress:x.account.waitress,total:v,cash:c,transfer:tr,cashReceived:received,change,method:m,ref:reference.value,cogs,grossProfit:v-cogs,account:JSON.parse(JSON.stringify(x.account))};S.sales.push(sale);x.account=null;save(`Pago ${sale.id} ${x.name}`);receipt(sale)}
function receiptItems(items){let map={};for(const i of items||[]){let k=i.id||i.name,m=map[k]||(map[k]={name:i.name,qty:0,price:i.price});m.qty+=i.qty||1}return Object.values(map)}
function receiptPlayerDetail(a,name){let items=[];for(const r of a.rounds||[])if(r.loser===name)items.push(...(r.items||[]),{id:'game-'+r.id,name:'Partida de billar',qty:1,price:r.gameFee||GAME});for(const e of a.playerExtras||[])if(e.player===name)items.push({...e,name:'EXTRA PERSONAL · '+e.name});return receiptItems(items)}
function receiptDetail(sale){let a=sale.account;if(!a)return '';if(sale.player){let items=receiptPlayerDetail(a,sale.player);return `<div class="receiptDetail"><h3>Detalle del consumo · ${sale.player}</h3>${items.length?items.map(i=>`<div class="item"><span>${i.name} ×${i.qty}<br><small>${COP(i.price)} c/u</small></span><b>${COP(i.price*i.qty)}</b></div>`).join(''):'<div class="item"><span>Sin detalle de productos</span></div>'}</div>`}if((a.rounds||[]).length||(a.playerExtras||[]).length){let names=[...new Set([...(a.rounds||[]).map(r=>r.loser),...(a.playerExtras||[]).map(e=>e.player)].filter(Boolean))];return `<div class="receiptDetail"><h3>Consumo total por jugador</h3>${names.map(n=>{let items=receiptPlayerDetail(a,n),sub=items.reduce((z,i)=>z+i.price*i.qty,0);return `<div class="receiptPlayer"><h4>👤 ${n} · ${COP(sub)}</h4>${items.map(i=>`<div class="item"><span>${i.name} ×${i.qty}</span><b>${COP(i.price*i.qty)}</b></div>`).join('')}</div>`}).join('')}</div>`}if((a.consumptionRounds||[]).length||(a.consumptionExtras||[]).length){return `<div class="receiptDetail"><h3>Rondas y extras de consumo</h3>${(a.consumptionRounds||[]).map((r,k)=>`<div class="receiptPlayer"><h4>Ronda ${k+1} · ${r.requester||'Cuenta general'} · ${COP(consumptionRoundTotal(r))}</h4>${(r.items||[]).map(i=>`<div class="item"><span>${i.name} ×${i.qty}</span><b>${COP(i.price*i.qty)}</b></div>`).join('')}</div>`).join('')}${(a.consumptionExtras||[]).map(e=>`<div class="item"><span>EXTRA · ${e.responsible} → ${e.beneficiary}<br><small>${e.name} ×${e.qty}</small></span><b>${COP(e.price*e.qty)}</b></div>`).join('')}</div>`}let items=receiptItems(a.loose||[]);return `<div class="receiptDetail"><h3>Detalle del consumo</h3>${items.map(i=>`<div class="item"><span>${i.name} ×${i.qty}</span><b>${COP(i.price*i.qty)}</b></div>`).join('')}</div>`}
function receipt(sale){let cashInfo='';if(sale.method==='Efectivo'){cashInfo=`<div class="item"><span>Efectivo recibido</span><b>${COP(sale.cashReceived||sale.total)}</b></div><div class="item"><span>Cambio devuelto</span><b>${COP(Math.max(0,sale.change||0))}</b></div>`}else if(sale.method==='Mixto'){cashInfo=`<div class="item"><span>Transferencia</span><b>${COP(sale.transfer||0)}</b></div><div class="item"><span>Efectivo aplicado</span><b>${COP(sale.cash||0)}</b></div><div class="item"><span>Efectivo recibido</span><b>${COP(sale.cashReceived||0)}</b></div><div class="item"><span>Cambio devuelto</span><b>${COP(Math.max(0,sale.change||0))}</b></div>`}else{cashInfo=`<div class="item"><span>Transferencia</span><b>${COP(sale.transfer||sale.total)}</b></div>`}modal(`<div class="receipt"><h2>🎱 Billares La Herradura Club</h2><h3>Recibo ${sale.id}</h3><p>${new Date(sale.ts).toLocaleString('es-CO')}<br>${sale.table} · ${sale.group}${sale.player?`<br>Jugador: <b>${sale.player}</b>`:''}<br>Mesera: ${sale.waitress}</p><hr>${receiptDetail(sale)}<hr><div class="total">TOTAL PAGADO ${COP(sale.total)}</div><div class="item"><span>Método</span><b>${sale.method}</b></div>${cashInfo}<h2 class="green">PAGADO ✓</h2></div><button class="gold wide noPrint" onclick="window.print()">🖨️ Imprimir</button><button class="wide noPrint" onclick="closeModal();showTables('${String(sale.table||'').startsWith('Consumo')?'consumo':'billar'}')">← Volver a mesas</button>`) }
function move(id){let f=t(id),free=S.tables.filter(x=>!x.account);if(f.type==='billar'&&pendingTotal(f.account)>0)return alert('Termina o asigna la partida actual antes de trasladar la cuenta.');modal(`${modalNav("openAccount('${id}')",'Orden')}<h2>⇄ Trasladar cuenta</h2><p>${f.account.group} · ${COP(closedTotal(f.account))}</p><div class="field"><label>Mesa destino</label><select id="dest">${free.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></div><p class="notice compact">Se conservan saldo, partidas, jugadores, consumos e historial.</p><button class="gold wide" onclick="confirmMove('${id}')">Confirmar traslado</button>`)}
function confirmMove(id){let f=t(id),d=t(dest.value);f.account.history.push(stamp()+` · Traslado ${f.name} → ${d.name}`);d.account=f.account;if(d.type==='billar'&&!d.account.activeRound)d.account.activeRound=newRound('Nueva partida tras traslado');if(d.type==='consumo')d.account.activeRound=null;f.account=null;save(`Traslado ${f.name} a ${d.name}`);closeModal();showTables(d.type)}
function openCustomer(id){window.open(`customer.html?table=${encodeURIComponent(id)}&theme=${encodeURIComponent(S.uiSettings?.customerTheme||'premium')}`,'cliente_'+id)}
function previewCustomer(id){window.open(`customer.html?table=${encodeURIComponent(id)}&theme=${encodeURIComponent(S.uiSettings?.customerTheme||'premium')}`,'cliente_'+id)}
function setTheme(kind,val){S.uiSettings=S.uiSettings||{};S.uiSettings[kind+'Theme']=val;save('Apariencia: '+kind+' = '+val);renderAppearance();if(kind==='billar'||kind==='consumo')showTables(kind)}
function applyVisualPreset(name){const presets={herraduraos:{billarTheme:'herraduraos',consumoTheme:'herraduraos',customerTheme:'herraduraos'},victoria:{billarTheme:'victoria',consumoTheme:'grand',customerTheme:'grand'},grandpremium:{billarTheme:'grandpremium',consumoTheme:'grand',customerTheme:'grand'},signature:{billarTheme:'signature',consumoTheme:'signature',customerTheme:'signature'},executive:{billarTheme:'executive',consumoTheme:'executive',customerTheme:'executive'},emerald:{billarTheme:'emerald',consumoTheme:'emerald',customerTheme:'emerald'},obsidian:{billarTheme:'obsidian',consumoTheme:'obsidian',customerTheme:'obsidian'},grand:{billarTheme:'grand',consumoTheme:'grand',customerTheme:'grand'},classic:{billarTheme:'herradura',consumoTheme:'elegante',customerTheme:'premium'}};if(!presets[name])return;S.uiSettings={...(S.uiSettings||{}),...presets[name]};save('Apariencia completa: '+name);renderAppearance()}
function renderAppearance(){let b=document.getElementById('appearancePanel');if(!b)return;let opts=(kind,vals)=>vals.map(([v,n])=>`<button class="themeChoice ${(S.uiSettings?.[kind+'Theme']||'')===v?'chosen':''}" onclick="setTheme('${kind}','${v}')">${n}</button>`).join('');b.innerHTML=`<h3>🎨 Apariencia</h3><p class="muted">Cambia el estilo visual sin modificar cuentas, inventario ni precios.</p><b>✨ Diseños completos prediseñados</b><p class="muted">Un toque cambia Billar, Consumo y Pantalla del cliente al mismo estilo.</p><div class="themePicker presetPicker"><button class="themeChoice" onclick="applyVisualPreset('herraduraos')">✨ Herradura OS Completo</button><button class="themeChoice" onclick="applyVisualPreset('victoria')">🏆 Herradura Victoria</button><button class="themeChoice" onclick="applyVisualPreset('grandpremium')">👑 Grand Premium</button><button class="themeChoice" onclick="applyVisualPreset('signature')">✦ Signature Club</button><button class="themeChoice" onclick="applyVisualPreset('executive')">🖋️ Executive Lounge</button><button class="themeChoice" onclick="applyVisualPreset('emerald')">💚 Emerald Club</button><button class="themeChoice" onclick="applyVisualPreset('obsidian')">◆ Obsidian Gold</button><button class="themeChoice" onclick="applyVisualPreset('grand')">🥂 Grand Club</button><button class="themeChoice" onclick="applyVisualPreset('classic')">🎱 Clásico limpio</button></div><b>Mesas de billar</b><div class="themePicker">${opts('billar',[['victoria','🏆 Herradura Victoria'],['herraduraos','✨ Herradura OS'],['grandpremium','👑 Herradura Grand Premium'],['maestro','🎱 Herradura Maestro'],['signature','✦ Herradura Signature'],['executive','🖋️ Executive Lounge'],['emerald','💚 Emerald Club'],['obsidian','◆ Obsidian Gold'],['grand','🎱 Herradura Grand Club'],['herradura','🎱 Herradura Clásico'],['vip','👑 Herradura Moderno'],['luxury','💎 Herradura Luxury'],['azul','🔷 Azul Premium'],['madera','🪵 Madera & Paño'],['minimal','✨ Minimalista']])}</div><b>Mesas de consumo</b><div class="themePicker">${opts('consumo',[['herraduraos','✨ Herradura OS'],['maestro','🎱 Herradura Maestro'],['signature','✦ Herradura Signature'],['executive','🖋️ Executive Lounge'],['emerald','💚 Emerald Club'],['obsidian','◆ Obsidian Gold'],['grand','🥂 Herradura Grand Lounge'],['elegante','🍺 Bar Elegante'],['vip','👑 Salón VIP'],['luxury','💎 Luxury Bar'],['ambar','🥃 Ámbar Premium'],['azul','🌙 Azul Nocturno'],['minimal','✨ Minimalista']])}</div><b>Pantalla del cliente</b><div class="themePicker">${opts('customer',[['herraduraos','✨ Herradura OS'],['maestro','🎱 Herradura Maestro'],['signature','✦ Herradura Signature'],['executive','🖋️ Executive Lounge'],['emerald','💚 Emerald Club'],['obsidian','◆ Obsidian Gold'],['grand','🎱 Herradura Grand Club'],['premium','🏆 Herradura Premium'],['vip','👑 Cliente VIP'],['luxury','💎 Luxury TV'],['felt','🎱 Paño Verde'],['nocturno','🌙 Nocturno'],['minimal','✨ Minimalista']])}</div>`}
function invMin(p){return p.minStock==null?(S.inventorySettings?.defaultMin??5):p.minStock}
function stockState(p){let n=S.inventory[p.id]||0,m=invMin(p);return n<=0?'agotado':n<=m?'bajo':'ok'}
function renderInventory(){if(!catalog.length)return;let q=(document.getElementById('invSearch')?.value||'').toLowerCase(),stocks=catalog.filter(p=>p.type==='stock'),low=stocks.filter(p=>stockState(p)!=='ok'),value=stocks.reduce((z,p)=>z+(S.inventory[p.id]||0)*unitCost(p),0),saleValue=stocks.reduce((z,p)=>z+(S.inventory[p.id]||0)*(+p.price||0),0),expectedProfit=saleValue-value;inv.innerHTML=`<div class="invKpis"><div class="card"><small>Productos</small><strong>${stocks.length}</strong></div><div class="card"><small>Stock bajo</small><strong class="${low.length?'red':''}">${low.length}</strong></div><div class="card"><small>Agotados</small><strong>${stocks.filter(p=>stockState(p)==='agotado').length}</strong></div><div class="card"><small>Valor a costo</small><strong>${COP(value)}</strong></div>${inventoryAdmin?`<div class="card"><small>💰 Venta esperada</small><strong>${COP(saleValue)}</strong></div><div class="card"><small>📈 Utilidad bruta esperada</small><strong class="${expectedProfit<0?'red':'green'}">${COP(expectedProfit)}</strong></div>`:''}</div>${low.length?`<div class="notice invAlert">⚠️ <b>${low.length} producto(s) requieren atención.</b> ${low.slice(0,5).map(p=>simpleName(p.name)).join(' · ')}${low.length>5?'…':''}</div>`:''}<div class="invToolbar"><button class="${inventoryAdmin?'greenBtn':'gold'}" onclick="inventoryAccess()">${inventoryAdmin?'🔓 Administración habilitada':'🔐 Acceso administradora'}</button>${inventoryAdmin?'<button onclick="newInventoryProduct()">➕ Nuevo producto</button><button onclick="inventoryHistory()">📋 Movimientos</button>':''}</div><div class="invLegend">${inventoryAdmin?'Puedes crear productos, modificar precio de compra/venta y ajustar existencias.':'Vista de consulta. Costos y utilidades solo son visibles para la Administradora.'}</div><div class="invTable"><table><tr><th>Producto</th><th>Existencia</th><th>Mínimo</th>${inventoryAdmin?'<th>Compra</th>':''}<th>Venta</th>${inventoryAdmin?'<th>Utilidad/u.</th><th>Margen</th><th>Acciones</th>':''}</tr>${stocks.filter(p=>(p.name+' '+p.category).toLowerCase().includes(q)).map(p=>{let n=S.inventory[p.id]||0,st=stockState(p),cost=unitCost(p),profit=(p.price||0)-cost,margin=p.price?Math.round(profit/p.price*100):0;return `<tr class="stock-${st}"><td><b>${simpleName(p.name)}</b><br><small>${p.category||'SIN CATEGORÍA'}</small>${st==='bajo'?'<br><span class="stockBadge warn">⚠️ STOCK BAJO</span>':st==='agotado'?'<br><span class="stockBadge out">AGOTADO</span>':''}</td><td class="${st!=='ok'?'red':''}"><b>${n}</b></td><td>${invMin(p)}</td>${inventoryAdmin?`<td>${COP(cost)}</td>`:''}<td>${COP(p.price)}</td>${inventoryAdmin?`<td class="${profit<0?'red':'green'}"><b>${COP(profit)}</b></td><td>${margin}%</td><td><button class="mini" onclick="adjustInventory('${p.id}')">± Stock</button> <button class="mini" onclick="editInventoryProduct('${p.id}')">✏️</button></td>`:''}</tr>`}).join('')}</table></div>`}
function inventoryAccess(){if(inventoryAdmin){inventoryAdmin=false;renderInventory();return}let pin=prompt('PIN de Administradora:');if(pin!==ADMIN_PIN)return alert('PIN incorrecto. No se realizaron cambios.');inventoryAdmin=true;S.audit.push({ts:new Date().toISOString(),note:'Acceso de administradora a inventario'});save();renderInventory()}
function requireInventoryAdmin(){if(!inventoryAdmin){alert('Esta función requiere autorización de la Administradora principal.');return false}return true}
function adjustInventory(pid){if(!requireInventoryAdmin())return;let p=catalog.find(x=>x.id===pid),cur=S.inventory[pid]||0;modal(`${modalNav("closeModal();showView('inventory')",'Inventario')}<h2>📦 Ajustar existencia</h2><div class="card inner"><b>${simpleName(p.name)}</b><br>Existencia actual: <span class="total">${cur}</span></div><div class="field"><label>Tipo de movimiento</label><select id="invMoveType"><option value="entry">➕ Entrada / compra</option><option value="return">↩️ Devolución a stock</option><option value="loss">➖ Merma / daño / faltante</option><option value="correction">🧮 Corrección de conteo</option></select></div><div class="field"><label>${'Cantidad (para corrección escribe la existencia final)'}</label><input id="invMoveQty" type="number" inputmode="decimal" min="0" step="1"></div><div class="field"><label>Motivo / observación</label><input id="invMoveNote" placeholder="Ej. Compra proveedor, devolución mesa 3…"></div><button class="gold wide" onclick="saveInventoryMove('${pid}')">💾 Guardar movimiento</button>`)}
function saveInventoryMove(pid){if(!requireInventoryAdmin())return;let p=catalog.find(x=>x.id===pid),type=invMoveType.value,q=+invMoveQty.value,note=invMoveNote.value.trim();if(!Number.isFinite(q)||q<0)return alert('Indica una cantidad válida.');let before=S.inventory[pid]||0,after=type==='correction'?q:type==='loss'?before-q:before+q;if(after<0&&!confirm(`La existencia quedará en ${after}. ¿Continuar?`))return;S.inventory[pid]=after;S.inventoryMovements.push({id:Date.now(),ts:new Date().toISOString(),productId:pid,product:simpleName(p.name),type,qty:q,before,after,note});save(`Inventario ${simpleName(p.name)}: ${before} → ${after}`);closeModal();showView('inventory')}
function newInventoryProduct(){if(!requireInventoryAdmin())return;inventoryProductForm()}
function editInventoryProduct(pid){if(!requireInventoryAdmin())return;inventoryProductForm(catalog.find(x=>x.id===pid))}
function inventoryProductForm(p){let editing=!!p;modal(`${modalNav("closeModal();showView('inventory')",'Inventario')}<h2>${editing?'✏️ Editar producto':'➕ Crear producto'}</h2><div class="field"><label>Nombre</label><input id="ipName" value="${editing?esc(simpleName(p.name)):''}"></div><div class="row"><div class="field"><label>Categoría</label><input id="ipCat" value="${editing?esc(p.category||''):''}" placeholder="CERVEZAS"></div><div class="field"><label>Precio de venta</label><input id="ipPrice" type="number" inputmode="numeric" value="${editing?p.price||0:''}"></div></div><div class="row"><div class="field"><label>Existencia</label><input id="ipStock" type="number" inputmode="numeric" value="${editing?S.inventory[p.id]||0:''}"></div><div class="field"><label>Alerta mínima</label><input id="ipMin" type="number" inputmode="numeric" value="${editing?invMin(p):5}"></div></div><div class="field"><label>Costo unitario (opcional)</label><input id="ipCost" type="number" inputmode="numeric" value="${editing?p.cost||0:''}"></div><button class="gold wide" onclick="saveInventoryProduct('${editing?p.id:''}')">💾 ${editing?'Guardar cambios':'Crear producto'}</button>`)}
function saveInventoryProduct(pid){if(!requireInventoryAdmin())return;let name=ipName.value.trim(),category=ipCat.value.trim().toUpperCase()||'OTROS',price=+ipPrice.value||0,stock=+ipStock.value||0,minStock=+ipMin.value||0,cost=+ipCost.value||0;if(!name)return alert('Escribe el nombre del producto.');let before=pid?(S.inventory[pid]||0):0;if(pid){let custom=(S.customProducts||[]).find(x=>x.id===pid);if(custom){Object.assign(custom,{name,category,price,minStock,cost});S.inventory[pid]=stock}else{S.productOverrides=S.productOverrides||{};S.productOverrides[pid]={...(S.productOverrides[pid]||{}),name,category,price,minStock,cost};S.inventory[pid]=stock}}else{pid='custom-'+Date.now();S.customProducts.push({id:pid,name,category,price,stock,type:'stock',recipe:[],minStock,cost});S.inventory[pid]=stock}refreshCatalog();S.inventoryMovements.push({id:Date.now(),ts:new Date().toISOString(),productId:pid,product:name,type:'product-edit',qty:stock-before,before,after:stock,note:`Producto creado/modificado por Administradora · costo ${COP(cost)} · venta ${COP(price)}`});save(`Producto inventario guardado: ${name}`);closeModal();showView('inventory')}
function inventoryHistory(){if(!requireInventoryAdmin())return;let rows=(S.inventoryMovements||[]).slice().reverse().slice(0,100);modal(`${modalNav("closeModal();showView('inventory')",'Inventario')}<h2>📋 Historial de inventario</h2><p><small>Últimos ${rows.length} movimientos. Cada ajuste conserva existencia anterior y nueva.</small></p>${rows.length?rows.map(m=>`<div class="item"><span><b>${m.product}</b><br><small>${new Date(m.ts).toLocaleString('es-CO')} · ${m.type}${m.note?' · '+m.note:''}</small></span><span>${m.before} → <b>${m.after}</b></span></div>`).join(''):'<div class="notice">Aún no hay movimientos manuales.</div>'}`)}
function renderSales(){salesList.innerHTML=S.sales.slice().reverse().map(x=>`<div class="item"><span>${x.id}<br><small>${x.waitress} · ${x.table}</small></span><b>${COP(x.total)}</b></div>`).join('')||'Sin ventas todavía.'}
function addExpense(){let n=expenseName.value.trim(),v=+expenseValue.value;if(!n||!v)return;S.expenses.push({name:n,value:v,ts:new Date().toISOString()});save(`Gasto ${n}`);expenseName.value='';expenseValue.value='';renderExpenses()}
function renderExpenses(){expenseList.innerHTML=S.expenses.slice().reverse().map(x=>`<div class="item"><span>${x.name}<br><small>${new Date(x.ts).toLocaleString('es-CO')}</small></span><b>${COP(x.value)}</b></div>`).join('')}
function startShift(){let name=prompt('Nombre de la mesera / responsable del turno:');if(!name)return;S.waitresses.includes(name)||S.waitresses.push(name);S.shifts.push({id:Date.now(),name,start:new Date().toISOString(),closed:false});save(`Turno abierto ${name}`);renderShift()}
function shiftClose(){let open=S.shifts.filter(x=>!x.closed);if(!open.length)return alert('No hay turno abierto.');let s=open[open.length-1];s.closed=true;s.end=new Date().toISOString();s.inventory=JSON.parse(JSON.stringify(S.inventory));save(`Cierre turno ${s.name}`);renderShift();alert('Cierre guardado. El inventario actual queda como entrega al siguiente turno.')}
function renderShift(){let open=S.shifts.filter(x=>!x.closed).slice(-1)[0];shiftInfo.innerHTML=open?`<p class="green">Turno abierto: <b>${open.name}</b><br>${new Date(open.start).toLocaleString('es-CO')}</p>`:'<p>No hay turno abierto.</p>'}
function renderReports(){let rev=S.sales.reduce((s,x)=>s+x.total,0),exp=S.expenses.reduce((s,x)=>s+x.value,0);monthly.innerHTML=`<div class="kpis"><div class="card kpi"><small>Ingresos</small><strong>${COP(rev)}</strong></div><div class="card kpi"><small>Egresos</small><strong>${COP(exp)}</strong></div><div class="card kpi"><small>Resultado preliminar</small><strong>${COP(rev-exp)}</strong></div><div class="card kpi"><small>Ventas</small><strong>${S.sales.length}</strong></div></div>`;let map={};for(const s of S.sales){let m=map[s.waitress]||(map[s.waitress]={total:0,mich:0,products:{}});m.total+=s.total;let items=[...(s.account.loose||[]),...(s.account.rounds||[]).flatMap(r=>r.items||[]),...(s.account.consumptionRounds||[]).flatMap(r=>r.items||[]),...(s.account.consumptionExtras||[])];for(const i of items){m.products[i.name]=(m.products[i.name]||0)+i.qty;if(i.name.toLowerCase().includes('michel'))m.mich+=i.qty}}waitressReport.innerHTML=Object.entries(map).sort((a,b)=>b[1].total-a[1].total).map(([n,m],i)=>`<div class="item"><span>${i===0?'🏆 ':''}<b>${n}</b><br><small>Micheladas: ${m.mich} · ${Object.values(m.products).reduce((a,b)=>a+b,0)} productos</small></span><b>${COP(m.total)}</b></div>`).join('')||'Aún no hay ventas registradas.'}
function downloadBackup(){let b=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='la-herradura-respaldo-v4-1.json';a.click()}
const modalEl=document.getElementById('modal'),payFieldsEl=document.getElementById('payFields')||{};renderHome();if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js?v=4.19.13',{updateViaCache:'none'}).then(r=>r.update()));
